import { useState, useMemo } from "react";
import {
  Box,
  CircularProgress,
  Typography,
  Button,
  TextField,
  InputAdornment,
  IconButton,
  Link,
} from "@mui/material";
import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";
import BaseCard from "../../../components/Cards/Card";
import { useTheme } from "@mui/material/styles";
import useMediaQuery from "@mui/material/useMediaQuery";
import { useFormik } from "formik";
import { toast } from "react-hot-toast";
import { useNavigate, useLocation, useSearchParams } from "react-router-dom";
import { useSelector } from "react-redux";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const RuleRow = ({ ok, label, showError }) => {
  const textColor = ok ? "#4CC66E" : showError ? "#FF4444" : "#AAAAAA";

  return (
    <Box sx={{ display: "flex", alignItems: "center", gap: 1, mt: 0.5 }}>
      <Box
        sx={{
          display: "inline-flex",
          justifyContent: "center",
          alignItems: "center",
          width: 18,
          height: 18,
          borderRadius: "50%",
          border: ok ? "none" : "2px solid #666666",
          background: ok ? "#4CC66E" : "transparent",
          position: "relative",
        }}
      >
        {ok ? (
          <Box
            sx={{
              width: 5,
              height: 9,
              borderRight: "2px solid #000",
              borderBottom: "2px solid #000",
              transform: "rotate(45deg)",
              mb: 0.5,
            }}
          />
        ) : (
          <Box sx={{ position: "relative", width: 8, height: 8 }}>
            <Box
              sx={{
                position: "absolute",
                width: "100%",
                height: 2,
                background: showError ? "#FF4444" : "#666666",
                transform: "rotate(45deg)",
                top: "50%",
                left: 0,
                marginTop: -0.5,
              }}
            />
            <Box
              sx={{
                position: "absolute",
                width: "100%",
                height: 2,
                background: showError ? "#FF4444" : "#666666",
                transform: "rotate(-45deg)",
                top: "50%",
                left: 0,
                marginTop: -0.5,
              }}
            />
          </Box>
        )}
      </Box>
      <Typography variant="caption" sx={{ color: textColor }}>
        {label}
      </Typography>
    </Box>
  );
};

const PasswordChecklist = ({ password, showError }) => {
  const rules = useMemo(
    () => ({
      length: password.length >= 8,
      upper: /[A-Z]/.test(password),
      lower: /[a-z]/.test(password),
      number: /[0-9]/.test(password),
      special: /[!@#$%^&*()[\]{}\-_+=~`|:;"'<>,.?/\\]/.test(password),
    }),
    [password],
  );
  return (
    <Box sx={{ mt: 1, mb: 1.5 }}>
      <RuleRow
        ok={rules.length}
        label="Minimum 8 characters"
        showError={showError && !rules.length}
      />
      <RuleRow
        ok={rules.upper}
        label="At least one uppercase letter"
        showError={showError && !rules.upper}
      />
      <RuleRow
        ok={rules.lower}
        label="At least one lowercase letter"
        showError={showError && !rules.lower}
      />
      <RuleRow
        ok={rules.number}
        label="At least one number"
        showError={showError && !rules.number}
      />
      <RuleRow
        ok={rules.special}
        label="At least one special character"
        showError={showError && !rules.special}
      />
    </Box>
  );
};

const ForgetSetPassword = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const navigate = useNavigate();
  const location = useLocation();
  const { otpData } = useSelector((state) => state.auth);
  const [searchParams] = useSearchParams();

  const urlEmail = searchParams.get("email");
  const urlOtp = searchParams.get("otp");

  const email = urlEmail || location.state?.email || otpData?.email;
  const otp = urlOtp || location.state?.code || otpData?.otp;

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showPwd, setShowPwd] = useState(false);
  const [showConfirmPwd, setShowConfirmPwd] = useState(false);

  const validate = (values) => {
    const errors = {};
    if (!values.password) {
      errors.password = "Password is required";
    } else {
      const pwd = values.password;
      const hasLen = pwd.length >= 8;
      const hasLower = /[a-z]/.test(pwd);
      const hasUpper = /[A-Z]/.test(pwd);
      const hasNum = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()[\]{}\-_+=~`|:;"'<>,.?/\\]/.test(pwd);

      if (!(hasLen && hasLower && hasUpper && hasNum && hasSpecial)) {
        errors.password = "Password is too weak";
      }
    }
    if (!values.confirmPassword) {
      errors.confirmPassword = "Confirm password is required";
    } else if (values.confirmPassword !== values.password) {
      errors.confirmPassword = "Passwords do not match";
    }
    return errors;
  };

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      email: email || "",
      password: "",
      confirmPassword: "",
    },
    validate,
    onSubmit: async (values) => {
      if (!email || !otp) {
        toast.error(
          "Missing verification session. Please try the forget password process again.",
        );
        return;
      }

      setIsSubmitting(true);
      try {
        const response = await fetch(`${BASE_URL}/auth/reset-password`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            email,
            otp,
            newPassword: values.password,
          }),
        });

        const data = await response.json();

        if (!response.ok || data.error) {
          throw new Error(data.message || "Failed to reset password");
        }

        toast.success(data.message || "Password reset successfully!");
        setTimeout(() => navigate("/"), 1200);
      } catch (err) {
        toast.error(err.message);
      } finally {
        setIsSubmitting(false);
      }
    },
  });

  return (
    <Box sx={{ width: "100%", display: "flex", justifyContent: "center" }}>
      <BaseCard
        maxWidth={isMobile ? "100%" : 400}
        sx={{
          width: isMobile ? "100%" : 400,
          p: 4,
          backgroundColor: "rgba(0, 0, 0, 0.7)", // Semi-transparent black
          backdropFilter: "blur(16px)", // Glassmorphism effect
          border: "1px solid #4CC66E", // Premium green full border
          borderRadius: "16px",
          boxShadow: "0 8px 32px 0 rgba(0, 0, 0, 0.8)",
        }}
      >
        <form onSubmit={formik.handleSubmit}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Logo Section */}
            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 1 }}>
              <img src="/favicon.svg" style={{ width: 100, height: 100, objectFit: "contain" }} alt="Logo" />
              
            </Box>

            <Box sx={{ textAlign: 'center' }}>
              <Typography variant="h5" sx={{ color: "#FFFFFF", mb: 0.5 }}>
                Set New Password
              </Typography>
              <Typography variant="body2" sx={{ color: "text.secondary" }}>
                Enter your new password below
              </Typography>
            </Box>

            <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                New Password<span style={{ color: "red" }}>*</span>
              </Typography>
              <TextField
                fullWidth
                name="password"
                type={showPwd ? "text" : "password"}
                placeholder="********"
                value={formik.values.password}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.submitCount > 0 && Boolean(formik.errors.password)
                }
                helperText={formik.submitCount > 0 && formik.errors.password}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowPwd(!showPwd)}
                        edge="end"
                        sx={{ color: "text.secondary" }}
                      >
                        {showPwd ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Box sx={{ display: "flex", flexDirection: "column", gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                {"Confirm Password"}
                <span style={{ color: "red" }}>*</span>
              </Typography>
              <TextField
                fullWidth
                name="confirmPassword"
                type={showConfirmPwd ? "text" : "password"}
                placeholder={"Confirm Password"}
                value={formik.values.confirmPassword}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.submitCount > 0 &&
                  Boolean(formik.errors.confirmPassword)
                }
                helperText={
                  formik.submitCount > 0 &&
                  formik.errors.confirmPassword
                }
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowConfirmPwd(!showConfirmPwd)}
                        edge="end"
                        sx={{ color: "text.secondary" }}
                      >
                        {showConfirmPwd ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <PasswordChecklist
              password={formik.values.password}
              showError={formik.touched.password}
            />

            <Button
              variant="contained"
              type="submit"
              disabled={isSubmitting}
              startIcon={
                isSubmitting && <CircularProgress size={20} color="inherit" />
              }
            >
              Reset Password
            </Button>

            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                mt: 1,
                gap: 0.5,
              }}
            >
              <Typography variant="body2" sx={{ color: "text.secondary" }}>
                Remember your password?
              </Typography>
              <Link
                component="button"
                variant="body2"
                onClick={() => navigate("/")}
                sx={{
                  color: "primary.main",
                  textDecoration: "none",
                  fontWeight: 600,
                  cursor: "pointer",
                  "&:hover": { textDecoration: "underline" },
                }}
              >
                Sign In
              </Link>
            </Box>
          </Box>
        </form>
      </BaseCard>
    </Box>
  );
};

export default ForgetSetPassword;
